var EXAMPLE='<style>\n  h1 { color: darkblue; }\n  p { font-size: 20px; }\n</style>\n<h1>Olá!</h1>\n<p>Edite este código.</p>\n<ul>\n  <li>Item 1</li>\n  <li>Item 2</li>\n</ul>';

function frameDoc(code){return '<!DOCTYPE html><html lang="pt-BR"><head><meta charset="utf-8"><style>body{font-family:system-ui,Arial,sans-serif;color:#111;background:#fff;margin:12px}</style></head><body>'+code+'</body></html>';}

var MDN={h1:"HTML/Reference/Elements/html",h2:"HTML/Reference/Elements/Heading_Elements",h3:"HTML/Reference/Elements/a",h4:"HTML/Reference/Elements/ul",h5:"HTML/Reference/Elements/img",h6:"HTML/Reference/Elements/form",h7:"HTML/Reference/Elements/table",h8:"HTML/Reference/Elements/footer",h9:"HTML/Reference/Elements/video",c1:"CSS",c2:"CSS/font-size",c3:"CSS/padding",c4:"CSS/Class_selectors",c5:"CSS/display",c6:"CSS/:hover",c7:"CSS/grid-template-columns",c8:"CSS/@media",c9:"CSS/var"};
var NOTE={h1:"<html> é a raiz do documento: todos os outros elementos ficam dentro dele.",h6:"<input type=\"button\"> ainda é válido, mas a MDN indica <button> como o jeito preferido de criar botões.",c5:"display define se o elemento é bloco ou em linha e como os filhos são organizados (fluxo, flex ou grid). gap é um atalho para row-gap e column-gap.",c7:"Flexbox é feito para uma dimensão (linha ou coluna). Grid é feito para duas dimensões: linhas e colunas."};
function mdnUrl(id){return "https://developer.mozilla.org/pt-BR/docs/Web/"+MDN[id];}
function refUrl(r){if(r[3])return "https://developer.mozilla.org/pt-BR/docs/Web/"+r[3];var b="https://developer.mozilla.org/pt-BR/docs/Web/",n=r[1];
if(r[0]==="H"){var m=n.match(/<([a-z0-9]+)>/);var t=m?m[1]:"html";if(/^h[1-6]$/.test(t))t="Heading_Elements";return b+"HTML/Reference/Elements/"+t;}
var k=n.split(/[\s\/(]/)[0];if(k==="prefers-reduced-motion")k="@media/prefers-reduced-motion";return b+"CSS/"+k;}
var ICON={h1:"🏠",h2:"🔠",h3:"🔗",h4:"📋",h5:"🖼️",h6:"📝",h7:"📊",h8:"🧩",h9:"🎬",c1:"🎨",c2:"🌈",c3:"📦",c4:"🏷️",c5:"↔️",c6:"👆",c7:"🔲",c8:"📱",c9:"🧪"};
var VIZ={
h1:`<div class="viz"><span class="c1">&lt;p&gt;<small>abre</small></span><span class="c2">Olá!<small>conteúdo</small></span><span class="c1">&lt;/p&gt;<small>fecha</small></span></div>`,
h3:`<div class="viz"><span class="c1">&lt;a<small>tag</small></span><span class="c3">href<small>atributo</small></span><span class="c4">"site.com"<small>endereço</small></span><span class="c2">Clique<small>texto</small></span><span class="c1">&lt;/a&gt;<small>fecha</small></span></div>`,
c1:`<div class="viz"><span class="c1">h1<small>seletor: quem</small></span><span class="c3">color<small>propriedade: o que</small></span><span class="c4">red<small>valor: como</small></span></div>`,
c3:`<div class="bm m"><small>margin (fora)</small><div class="bm bo"><small>border (borda)</small><div class="bm pa"><small>padding (dentro)</small><div class="bm co">conteúdo</div></div></div></div>`
};
function hl(code){return code.split("\n").map(function(line){var s=esc(line);
s=s.replace(/"[^"]*"/g,function(m){return '<span class="s">'+m+'</span>';});
s=s.replace(/(&lt;\/?)([a-zA-Z0-9]+)/g,'$1<span class="t">$2</span>');
if(line.indexOf(";")>-1||line.indexOf("{")>-1){s=s.replace(/([\w-]+)(?=\s*:\s)/g,'<span class="p">$1</span>');}
return s;}).join("\n");}
function renderLessons(track,box){
var html="",n=0;
LESSONS.forEach(function(l){if(l.t!==track)return;n++;
var doc=frameDoc(l.code).replace(/&/g,"&amp;").replace(/"/g,"&quot;");
html+=`<article class="card lesson" id="l-${l.id}"><div class="lh"><span class="num">${n}</span><h3>${esc(l.n)} <span class="done" data-chk="${l.id}"></span></h3><span class="ico">${ICON[l.id]}</span></div>`;
if(VIZ[l.id])html+=VIZ[l.id];
html+=`<div class="pair"><div class="browser"><div class="wb"><i></i><i></i><i></i><span>👀 Resultado</span></div><iframe sandbox title="Resultado: ${esc(l.n)}" srcdoc="${doc}"></iframe></div>`;
html+=`<div class="win"><div class="wb"><i></i><i></i><i></i><span>💻 Código</span></div><pre><code>${hl(l.code)}</code></pre></div></div>`;
html+=`<details><summary>📖 Ler explicação</summary>${l.tx.map(function(p){return "<p>"+esc(p)+"</p>";}).join("")}</details>`;
if(NOTE[l.id])html+=`<div class="note"><strong>📘 Segundo a MDN:</strong> ${esc(NOTE[l.id])}</div>`;
html+=`<div class="row"><button class="btn" data-try="${l.id}">✍️ Testar</button><a class="btn mdn" target="_blank" rel="noopener noreferrer" href="${mdnUrl(l.id)}">📘 MDN</a><a class="btn" target="_blank" rel="noopener noreferrer" href="${lib(l.n)}">🤟 Libras</a><button class="btn fill" data-go="perguntas">❓ Perguntas</button></div></article>`;});
document.getElementById(box).innerHTML=html;
}
function lib(t){return "https://www.youtube.com/results?search_query="+encodeURIComponent("libras "+t);}
function find(id){for(var i=0;i<LESSONS.length;i++)if(LESSONS[i].id===id)return LESSONS[i];return null;}
function refresh(){
var c=0;LESSONS.forEach(function(l){document.querySelectorAll('[data-chk="'+l.id+'"]').forEach(function(el){el.textContent=done[l.id]?"✓ Concluída":"";});if(done[l.id])c++;});
var t=LESSONS.length;tiles();
document.getElementById("pfill").style.width=(c/t*100)+"%";
document.getElementById("pbar").setAttribute("aria-valuenow",c);
document.getElementById("ptxt").textContent=c+" de "+t+" lições concluídas"+(c===t?" 🎉 Parabéns!":"");
}
document.addEventListener("click",function(e){
var b=e.target.closest("button");if(!b)return;
if(b.dataset.q){var l=find(b.dataset.q);var i=+b.dataset.i;var fb=document.querySelector('[data-fb="'+l.id+'"]');
document.querySelectorAll('[data-q="'+l.id+'"]').forEach(function(x){x.classList.remove("ok","bad");});
if(i===l.a){b.classList.add("ok");fb.className="fb ok";fb.textContent="✓ Certo! "+l.w;done[l.id]=true;save();refresh();toast("🎉 Muito bem!",1);}
else{b.classList.add("bad");fb.className="fb bad";fb.textContent="✗ Ainda não. Leia de novo e tente outra vez.";toast("🤔 Tente de novo",0);}}
else if(b.dataset.try){var l2=find(b.dataset.try);pg.value=l2.code;go("praticar");runPg();}
else if(b.dataset.go){go(b.dataset.go);}
});

var pg=document.getElementById("pgCode"),fr=document.getElementById("pgFrame"),tmr;
function runPg(){fr.srcdoc=frameDoc(pg.value);}
pg.value=EXAMPLE;
pg.addEventListener("input",function(){clearTimeout(tmr);tmr=setTimeout(runPg,300);});
document.getElementById("pgRun").onclick=runPg;
document.getElementById("pgReset").onclick=function(){pg.value=EXAMPLE;runPg();};

function renderGl(f){var h="",c=0;f=(f||"").toLowerCase();
GL.forEach(function(g){if(!f||g[0].toLowerCase().indexOf(f)>-1||g[1].toLowerCase().indexOf(f)>-1){c++;h+="<dt>"+esc(g[0])+"</dt><dd>"+esc(g[1])+' <a href="'+lib(g[0])+'" target="_blank" rel="noopener noreferrer">🤟 Buscar em Libras</a></dd>';}});
document.getElementById("gl").innerHTML=h;document.getElementById("gnone").hidden=c>0;}
